<?php $streamcreedTicket = is_array($rTicketInfo ?? null) ? $rTicketInfo : []; $streamcreedRequester = (string) ($streamcreedTicket['user']['username'] ?? 'User'); ?>
<section class="sc-ticket-view"><div class="sc-page-heading"><div><p class="sc-eyebrow">Support</p><h1><?php echo htmlspecialchars((string) ($streamcreedTicket['title'] ?? 'Ticket'), ENT_QUOTES, 'UTF-8'); ?></h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="tickets"><i class="fe-chevron-left" aria-hidden="true"></i> Back to tickets</a></div></div><div class="sc-ticket-thread"><?php foreach ($streamcreedTicket['replies'] ?? [] as $streamcreedReply): ?><article class="sc-ticket-message<?php echo !empty($streamcreedReply['admin_reply']) ? ' is-admin' : ''; ?>"><header><strong><?php echo !empty($streamcreedReply['admin_reply']) ? 'Admin' : htmlspecialchars($streamcreedRequester, ENT_QUOTES, 'UTF-8'); ?></strong><time><?php echo !empty($streamcreedReply['date']) ? date('Y-m-d H:i', intval($streamcreedReply['date'])) : '—'; ?></time></header><p><?php echo nl2br(htmlspecialchars((string) ($streamcreedReply['message'] ?? ''), ENT_QUOTES, 'UTF-8')); ?></p></article><?php endforeach; ?><?php if (empty($streamcreedTicket['replies'])): ?><div class="sc-table-state">This ticket has no replies.</div><?php endif; ?></div><div class="sc-page-actions sc-ticket-actions"><a class="sc-button sc-button-primary" href="ticket_view?id=<?php echo intval($streamcreedTicket['id'] ?? 0); ?>&admin_ui=legacy">Reply in full ticket view</a></div></section>
